package com.bank.consolidate;

import java.util.*;
import java.util.logging.*;

public class ConsolidateDemo {
    private static final Logger log = Logger.getLogger("Consolidate");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> mumbai = List.of(
            new Employee(1L, "Rajesh"), new Employee(2L, "Priya"));
        List<Employee> delhi = List.of(
            new Employee(2L, "Priya"),   // transferred — duplicate id
            new Employee(3L, "Amit"));
        ConsolidationService service = new ConsolidationService();

        List<Employee> master = service.merge(mumbai, delhi);
        log.info(() -> "Master size (deduped by id): " + master.size());
        master.forEach(e -> log.info(() -> "  id=" + e.id() + " name=" + e.name()));
    }
}

// ─── Would be in model/Employee.java ───
record Employee(Long id, String name) {}

// ─── Would be in service/ConsolidationService.java ───
class ConsolidationService {
    List<Employee> merge(List<Employee> a, List<Employee> b) {
        // concat: all of a then all of b, in order
        return java.util.stream.Stream
            .concat(a.stream(), b.stream())
            // dedupe by id: keep the first record per id
            .collect(java.util.stream.Collectors.collectingAndThen(
                java.util.stream.Collectors.toMap(
                    Employee::id, e -> e, (first, second) -> first,
                    LinkedHashMap::new),                 // preserve concat order
                m -> new ArrayList<>(m.values())));
    }
}
